     3	import hotel.rooms.Room;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	
     8	/**
     9	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    10	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    11	 * (half-even) at every step.
    12	 */
    13	public final class PriceCalculator {
    14	
    15	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.25");
    16	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    17	
    18	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    19	        int nights = 0;
    20	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    21	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    22	            subtotal = subtotal.add(nightPrice(room, night));
    23	            nights++;
    24	        }
    25	        BigDecimal discount = switch (ratePlan) {
    26	            case STANDARD -> cents(BigDecimal.ZERO);
    27	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    28	        };
    29	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    30	    }
    31	
    32	    BigDecimal nightPrice(Room room, LocalDate night) {
    33	        BigDecimal nightlyRate = room.nightlyRate();
    34	        if (isHighSeason(night)) {
    35	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    36	        }
    37	        return cents(nightlyRate);
    38	    }
    39	
    40	    static boolean isHighSeason(LocalDate date) {
    41	        return HighSeason.includes(date);
    42	    }
    43	
    44	    static BigDecimal cents(BigDecimal value) {
    45	        return value.setScale(2, RoundingMode.HALF_EVEN);
    46	    }
    47	}
